import { StudioProApi } from "@mendix/extensions-api";
import { createStudioProLogger } from "../config/logger";
import { Knowledgebase } from "../types/knowledgebase/knowledgebase";
import {
    Collection,
    MxCloudGenAIKeyImportData as KnowledgeBaseKeyData,
    MxCloudGenAICollectionsResponse,
    MxCloudGenAIKnowledgebaseFields,
} from "../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { Model } from "../types/model/model";
import {
    MxCloudGenAIKeyImportData,
    MxCloudGenAIModelFields,
    MxCloudGenAIResourceAPIResponse,
} from "../types/model/mxCloudGenAIModel";
import { getConstantValue } from "./constantUtils";
import { createNewModel } from "./modelUtils";

export const decodeAndParseKey = <T>(studioPro: StudioProApi, key: string): T => {
    const logger = createStudioProLogger(studioPro);
    try {
        const decodedJson = atob(key);
        const keyData: T = JSON.parse(decodedJson);
        return keyData;
    } catch (error) {
        logger.error(`Error decoding and parsing key`, error);
        throw new Error(`The key could not be parsed, make sure it is valid.`);
    }
};

export const invokeResourceAPI = async (
    studioPro: StudioProApi,
    model: Model
): Promise<MxCloudGenAIResourceAPIResponse | string> => {
    const logger = createStudioProLogger(studioPro);
    try {
        const mxCloudGenAIModelFields = model.providerFields as MxCloudGenAIModelFields;

        if (!mxCloudGenAIModelFields.key) {
            throw new Error("Model key is not configured.");
        }

        const keyValue = await getConstantValue(studioPro, mxCloudGenAIModelFields.key);

        if (!keyValue) {
            throw new Error(
                `Constant ${mxCloudGenAIModelFields.key.qualifiedName} does not have an accessible runtime value or default value.`
            );
        }

        const keyData: MxCloudGenAIKeyImportData = decodeAndParseKey(studioPro, keyValue);
        const proxyUrl: string = await studioPro.network.httpProxy.getProxyUrl(`${keyData.resourceBaseUrl}`);

        const response = await fetch(proxyUrl, {
            method: "GET",
            headers: {
                "Content-Type": "application/json",
                Accept: "*/*",
                "x-api-key": keyData.accessToken,
            },
            credentials: "omit",
        });

        if (response.status !== 200) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const responseBody: MxCloudGenAIResourceAPIResponse = await response.json();

        return responseBody;
    } catch (error) {
        logger.error("Error invoking MxCloud GenAI resource API:", error);
        return error instanceof Error ? error.message : "";
    }
};

